-- Contexto: rol, base, esquema y warehouse del lab
USE ROLE accountadmin;
USE DATABASE tb_101;
USE SCHEMA public;
USE WAREHOUSE tb_analyst_wh;

-- Sincroniza el catalogo de archivos del stage
ALTER STAGE archivos REFRESH;
-- Lista los archivos disponibles y su tamano
SELECT relative_path, size FROM DIRECTORY(@archivos);

-- Transcribe una llamada separando a cada hablante
SELECT AI_TRANSCRIBE(TO_FILE('@archivos', 'problema-servicio.mp3'),
                     {'timestamp_granularity': 'speaker'}) AS transcripcion;
